'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Float32Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Float32Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'a typed array instance has a `lastIndexOf` method', function test( t ) {
	var arr = new Float32Array( 2 );
	t.strictEqual( hasProp( arr, 'lastIndexOf' ), true, 'has property' );
	t.strictEqual( isFunction( arr.lastIndexOf ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a typed array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Float32Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.lastIndexOf.call( value, 1.0 );
		};
	}
});

tape( 'the method returns `-1` if operating on an empty typed array', function test( t ) {
	var arr;
	var idx;

	arr = new Float32Array();
	idx = arr.lastIndexOf( 1.0 );

	t.strictEqual( idx, -1, 'returns expected value' );
	t.end();
});

tape( 'the method returns `-1` if a value is not found', function test( t ) {
	var idx;
	var arr;

	arr = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	idx = arr.lastIndexOf( 10.0 );

	t.strictEqual( idx, -1, 'returns expected value' );
	t.end();
});

tape( 'the method returns the index of the last match', function test( t ) {
	var idx;
	var arr;

	arr = new Float32Array( [ 1.0, 2.0, 3.0, 2.0, 5.0 ] );
	idx = arr.lastIndexOf( 2.0 );

	t.strictEqual( idx, 3, 'returns expected value' );
	t.end();
});

tape( 'the method supports specifying a starting search index', function test( t ) {
	var idx;
	var arr;

	arr = new Float32Array( [ 1.0, 2.0, 3.0, 2.0, 4.0 ] );

	idx = arr.lastIndexOf( 2.0, 4 );
	t.strictEqual( idx, 3, 'returns expected value' );

	idx = arr.lastIndexOf( 2.0, 2 );
	t.strictEqual( idx, 1, 'returns expected value' );

	idx = arr.lastIndexOf( 3.0, 1 );
	t.strictEqual( idx, -1, 'returns expected value' );
	t.end();
});

tape( 'the method supports specifying a starting search index (negative)', function test( t ) {
	var idx;
	var arr;

	arr = new Float32Array( [ 1.0, 2.0, 3.0, 2.0, 2.0 ] );

	idx = arr.lastIndexOf( 2.0, -1 );
	t.strictEqual( idx, 4, 'returns expected value' );

	idx = arr.lastIndexOf( 2.0, -3 );
	t.strictEqual( idx, 1, 'returns expected value' );
	t.end();
});
